-- sqlcl_snapshot db/src/database/veranolink/tables/log_lote.sql:null:abd02990a89ba2e30d79889729adf01276a7e43f:create

create table veranolink.log_lote (
    id_lote           number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1
    cache 20 noorder nocycle nokeep noscale not null enable,
    project_id        number not null enable,
    contract_number   varchar2(50 byte),
    tipo_objeto       varchar2(10 byte) not null enable,
    accion            varchar2(10 byte) not null enable,
    fecha_ejecucion   timestamp(6) default systimestamp not null enable,
    resultado         varchar2(10 byte) not null enable,
    http_status       number,
    total_objetos     number,
    total_ok          number,
    total_fallo       number,
    payload_enviado   clob,
    mensaje_respuesta clob
);

alter table veranolink.log_lote
    add constraint ck_log_lote_accion
        check ( accion in ( 'CREATE', 'UPDATE' ) ) enable;

alter table veranolink.log_lote
    add constraint ck_log_lote_result
        check ( resultado in ( 'OK', 'FALLO', 'PARCIAL' ) ) enable;

alter table veranolink.log_lote
    add constraint ck_log_lote_tipo
        check ( tipo_objeto in ( 'WBS', 'ACTIVITY', 'MIXTO' ) ) enable;

alter table veranolink.log_lote
    add constraint pk_log_lote primary key ( id_lote )
        using index enable;

